  const sum = (A, f) => +A.reduce((x, y) => x + (+f(y) || 0), 0).toFixed(2);
  const save = v => { setDb('commissions', A => { A = A || []; return v.id && A.some(x => x.id === v.id) ? A.map(x => x.id === v.id ? v : x) : [{ ...v, id: Date.now() }, ...A]; }); toast(t('Commission saved'), v.agent); setForm(null); };
